const db=new DatabaseSync(process.env.DB_PATH||'data.sqlite'); db.exec('PRAGMA foreign_keys=ON');
function transaction(fn){db.exec('BEGIN IMMEDIATE');try{let result=fn();db.exec('COMMIT');return result}catch(e){db.exec('ROLLBACK');throw e}}
