function offlineKey(){return 'offlineOrders:'+me.username}function saveOffline(order){let q=JSON.parse(localStorage.getItem(offlineKey())||'[]');q.push(order);localStorage.setItem(offlineKey(),JSON.stringify(q))}async function flushOfflineOrders(){if(!me||!navigator.onLine)return;let key=offlineKey(),q=JSON.parse(localStorage.getItem(key)||'[]'),failed=[];for(let item of q){try{await post('orders',item)}catch(e){failed.push(item)}}localStorage.setItem(key,JSON.stringify(failed));if(q.length!==failed.length&&tab==='orders')await refresh()}const money=n=>'₹'+(Number(n||0)/100).toFixed(2);
function ledger(item){return stockBalance(db.prepare('SELECT qty FROM movements WHERE item_id=?').all(item).map(r=>r.qty))}
function avgRate(item,baseRate){let opening=db.prepare('SELECT opening FROM items WHERE id=?').get(item).opening;let receipts=db.prepare('SELECT COALESCE(SUM(qty),0) q,COALESCE(SUM(qty*rate_paise),0) v FROM purchases WHERE item_id=?').get(item);return movingAverageRate(opening,baseRate,receipts.q,receipts.v)}
function actor(req){const tok=(req.headers.cookie||'').match(/sid=([^;]+)/)?.[1];return sessions.get(tok)}
function send(res,status,obj,headers={}){res.writeHead(status,{'content-type':'application/json; charset=utf-8',...headers});res.end(JSON.stringify(obj))}
function body(req){return new Promise((ok,no)=>{let s='';req.on('data',d=>s+=d);req.on('end',()=>{try{ok(JSON.parse(s||'{}'))}catch(e){no(e)}})})}
function audit(u,a,e,id){db.prepare('INSERT INTO audit(actor,action,entity,entity_id) VALUES(?,?,?,?)').run(u.username,a,e,id||0)}
function reportPdf(lines){const clean=s=>String(s).replace(/[^\x20-\x7E]/g,'?').replace(/[()\\]/g,'\\$&'),commands=lines.map((s,i)=>'0 -'+(i?15:24)+' Td ('+clean(s)+') Tj').join(' '),body='BT /F1 14 Tf 50 800 Td (Monthly Audit Report) Tj /F1 9 Tf '+commands+' ET',objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+body.length+' >>\nstream\n'+body+'\nendstream'];let out='%PDF-1.4\n',offs=[0];for(let i=0;i<objs.length;i++){offs.push(out.length);out+=(i+1)+' 0 obj\n'+objs[i]+'\nendobj\n'}let x=out.length;out+='xref\n0 '+(objs.length+1)+'\n0000000000 65535 f \n';for(let i=1;i<offs.length;i++)out+=String(offs[i]).padStart(10,'0')+' 00000 n \n';out+='trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+x+'\n%%EOF';return out}
