function invoiceNo(){let y=new Date().getFullYear(),fy=(new Date().getMonth()>=3?y:y-1);let seq=db.prepare('SELECT COUNT(*) n FROM invoices WHERE number LIKE ?').get(`INV/${fy}-${String(fy+1).slice(-2)}/%`).n+1;return `INV/${fy}-${String(fy+1).slice(-2)}/${String(seq).padStart(4,'0')}`}
function pdf(i){const safe=s=>String(s).replace(/[^\x20-\x7E]/g,'?').replace(/[()\\]/g,'\\$&');const total=i.taxable_paise+i.cgst_paise+i.sgst_paise+i.igst_paise;const stream=`BT /F1 15 Tf 50 780 Td (${safe(i.number)}) Tj /F1 10 Tf 0 -28 Td (GST Tax Invoice | ${safe(i.customer)} | GSTIN ${safe(i.gstin)}) Tj 0 -22 Td (Description: ${safe(i.product)} | HSN ${safe(i.hsn)} | Qty: ${i.qty}) Tj 0 -22 Td (Taxable: INR ${(i.taxable_paise/100).toFixed(2)} | CGST: INR ${(i.cgst_paise/100).toFixed(2)} | SGST: INR ${(i.sgst_paise/100).toFixed(2)}) Tj 0 -22 Td (IGST: INR ${(i.igst_paise/100).toFixed(2)} | Invoice total: INR ${(total/100).toFixed(2)}) Tj ET`;
 const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];let out='%PDF-1.4\n',offs=[0];for(let i=0;i<objs.length;i++){offs.push(out.length);out+=`${i+1} 0 obj\n${objs[i]}\nendobj\n`}let x=out.length;out+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offs.length;i++)out+=String(offs[i]).padStart(10,'0')+' 00000 n \n';out+=`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`;return out}
