function runReport(from=null,to=null){let runs=db.prepare('SELECT r.*,p.name product_name,p.price_paise sell_price FROM runs r JOIN products p ON p.id=r.product_id WHERE (? IS NULL OR date(created_at)>=date(?)) AND (? IS NULL OR date(created_at)<=date(?)) ORDER BY r.id DESC').all(from,from,to,to);return runs.map(r=>{let lines=db.prepare('SELECT rl.*,i.name item_name FROM run_lines rl JOIN items i ON i.id=rl.item_id WHERE rl.run_id=?').all(r.id),material=lines.reduce((a,l)=>a+Math.round(l.actual*l.rate_paise),0),cost=Math.round((material+r.labour_paise+r.utilities_paise)/r.actual),flags=[];let yieldPct=variancePct(r.actual,r.expected);if(Math.abs(yieldPct)>3)flags.push(`Yield ${yieldPct>0?'+':''}${yieldPct.toFixed(0)}%`);for(let line of lines){let pct=variancePct(line.actual,line.planned);if(Math.abs(pct)>3)flags.push(`${line.item_name} ${pct>0?'+':''}${pct.toFixed(0)}%`)}return {...r,material_paise:Math.round(material),cost_paise:cost,margin_paise:r.sell_price-cost,yield_pct:Math.round(yieldPct),flags:flags.join(' · '),alert:flags.length>0}})}
function benchmark(req,res,u){try{const already=db.prepare("SELECT COUNT(*) n FROM audit WHERE action='benchmark complete'").get().n;if(already)return send(res,409,{error:'Benchmark already applied. Reset data.sqlite with npm run seed to replay.'});transaction(()=>{let buy=db.prepare("INSERT INTO purchases(item_id,qty,rate_paise,supplier) VALUES(1,60,4500,'Benchmark Supplier')").run().lastInsertRowid;db.prepare("INSERT INTO movements(item_id,qty,source,ref,note) VALUES(1,60,'purchase',?,'60 kg flour at ₹45/kg')").run('PUR-'+buy);let run=db.prepare('INSERT INTO runs(product_id,expected,actual,scrap,labour_paise,utilities_paise,created_by) VALUES(1,200,188,6,120000,60000,?)').run('floor').lastInsertRowid;let specs=[[1,40,40,4313],[2,10,10.5,14000],[3,1.2,1.2,20000],[4,200,194,250],[5,10,9,1500]];for(let [item,planned,actual,rate]of specs){db.prepare('INSERT INTO run_lines VALUES(?,?,?,?,?)').run(run,item,planned,actual,rate);db.prepare("INSERT INTO movements(item_id,qty,source,ref,note) VALUES(?,?, 'production issue',?,?)").run(item,-actual,'RUN-'+run,'Benchmark consumption')}db.prepare("INSERT INTO movements(item_id,qty,source,ref,note) VALUES(6,188,'production output',?,'188 good packets')").run('RUN-'+run);
let orderA=db.prepare("INSERT INTO orders(customer_id,salesman,qty,price_paise,status) VALUES(1,'salesa',150,5000,'submitted')").run().lastInsertRowid;db.prepare('INSERT OR IGNORE INTO order_lines VALUES(?,?,?,?)').run(orderA,1,150,5000);let inv=db.prepare('INSERT INTO invoices(order_id,number,taxable_paise,cgst_paise,sgst_paise,igst_paise) VALUES(?,?,?,?,?,0)').run(orderA,invoiceNo(),750000,18750,18750).lastInsertRowid;db.prepare("UPDATE orders SET status='dispatched' WHERE id=?").run(orderA);db.prepare("INSERT INTO movements(item_id,qty,source,ref,note) VALUES(6,-150,'dispatch',?,'Retailer A dispatch')").run('ORDER-'+orderA);db.prepare("INSERT INTO payments(invoice_id,amount_paise,ref) VALUES(?,400000,'Benchmark payment')").run(inv);let orderB=db.prepare("INSERT INTO orders(customer_id,salesman,qty,price_paise,status) VALUES(2,'salesb',120,5000,'submitted')").run().lastInsertRowid;db.prepare('INSERT OR IGNORE INTO order_lines VALUES(?,?,?,?)').run(orderB,1,120,5000);audit(u,'benchmark complete','scenario',orderB);audit(u,'posted benchmark production','run',run);audit(u,'dispatched Retailer A','order',orderA)});return send(res,200,{message:'Benchmark applied: flour 120 kg; oil 19.5 L; pouches 306; finished goods 88; yield −6%, oil +5%; invoice ₹7,875; outstanding ₹3,875. Distributor B needs 120; current stock is 88 (short 32).'})}catch(e){return send(res,500,{error:e.message})}}
